(()=>{function sync(){const top=document.querySelector('.top');document.documentElement.style.setProperty('--app-header-height',(Math.max(0,top?.getBoundingClientRect().bottom||74))+'px')}window.addEventListener('DOMContentLoaded',()=>{sync();const top=document.querySelector('.top');if(top)new ResizeObserver(sync).observe(top)});window.addEventListener('resize',sync);window.addEventListener('scroll',sync,{passive:true,capture:true})})();
(()=>{const pinned=new Map();function pin(el,target,kind='add'){if(!el||!target||pinned.has(el))return;const marker=document.createComment('header-control-origin');if(el.tagName==='BUTTON'&&el.type==='submit'&&el.form){const form=el.form;if(!form.id)form.id='header-form-'+Math.random().toString(36).slice(2);el.setAttribute('form',form.id)}el.before(marker);pinned.set(el,marker);if(target.classList.contains('shortcut-actions')){const label=el.getAttribute('aria-label')||el.title||el.textContent.trim();el.title=label;el.setAttribute('aria-label',label);el.classList.remove('btn','tree-add-solid','location-add');el.style.setProperty('border-radius','50%','important');el.classList.add('shortcut-circle',kind==='history'?'header-history-circle':'header-add-circle');el.innerHTML='<svg viewBox="0 0 24 24" aria-hidden="true">'+(kind==='history'?'<circle cx="12" cy="12" r="9"/><path d="M12 7v5l3 2"/>':'<path d="M12 5v14M5 12h14"/>')+'</svg>'}target.append(el)}function arrange(){for(const [el,marker]of pinned){if(!marker.isConnected){el.remove();pinned.delete(el)}}document.querySelectorAll('.view.show>.panel').forEach(panel=>{const head=panel.querySelector(':scope>.head'),content=panel.querySelector(':scope>.content');if(!head||!content)return;let dock=head.querySelector(':scope>.fixed-header-tools');if(!dock){dock=document.createElement('div');dock.className='fixed-header-tools';head.append(dock)}const actions=head.querySelector('.shortcut-actions');if(actions){pin(content.querySelector('#jobs-add'),actions);pin([...content.querySelectorAll('.ti-group-form>button')].find(b=>/^(?:\+\s*)?(?:Adicionar (?:grupo|tipo)|Novo grupo)$/i.test(b.textContent.trim())),actions);pin(content.querySelector('.location-toolbar .location-add'),actions);pin([...content.querySelectorAll('button')].find(b=>/^Histórico de transferências$/i.test(b.textContent.trim())),actions,'history')}for(const selector of ['.jobs-toolbar','.financial-list-controls','.location-toolbar']){for(const el of content.querySelectorAll(selector))pin(el,dock)}dock.hidden=!dock.querySelector('input:not([hidden]),select,button')})}window.addEventListener('DOMContentLoaded',()=>{let pending=false;new MutationObserver(()=>{if(pending)return;pending=true;queueMicrotask(()=>{pending=false;arrange()})}).observe(document.body,{childList:true,subtree:true,attributes:true,attributeFilter:['class']});arrange()})})();
(()=>{window.addEventListener('DOMContentLoaded',()=>{let queued=false;const searches=new Map();function refresh(){for(const [input,entry] of searches){if(!input.isConnected){entry.button.remove();searches.delete(input)}}document.querySelectorAll('.view.show>.panel>.head').forEach(head=>{const actions=head.querySelector('.shortcut-actions');if(!actions)return;head.querySelectorAll('.fixed-header-tools input[type="search"]').forEach(input=>{input.classList.add('account-sort','shared-header-search');if(!input.dataset.searchHint){input.dataset.searchHint=input.placeholder||'Buscar';if(!input.getAttribute('aria-label'))input.setAttribute('aria-label',input.dataset.searchHint);input.placeholder='Buscar…'}input.parentElement.classList.add('header-query-controls');if(searches.has(input))return;const button=document.createElement('button');button.type='button';button.className='shortcut-circle header-search-circle';button.title='Buscar';button.setAttribute('aria-label','Abrir busca');button.innerHTML='<svg viewBox="0 0 24 24" aria-hidden="true"><circle cx="10.5" cy="10.5" r="6.5"/><path d="m16 16 5 5"/></svg>';let open=!!input.value;function toggle(next){open=next;input.hidden=!open;input.classList.toggle('header-search-open',open);button.setAttribute('aria-expanded',String(open));button.setAttribute('aria-label',open?'Recolher busca':'Abrir busca');button.title=open?'Recolher busca':'Buscar';button.classList.toggle('search-has-query',!!input.value);if(open)input.focus()}button.onclick=()=>toggle(!open);input.addEventListener('keydown',e=>{if(e.key==='Escape'){e.preventDefault();toggle(false);button.focus()}});input.addEventListener('input',()=>button.classList.toggle('search-has-query',!!input.value));searches.set(input,{button});actions.append(button);toggle(open)})})}new MutationObserver(()=>{if(queued)return;queued=true;queueMicrotask(()=>{queued=false;refresh()})}).observe(document.body,{childList:true,subtree:true});refresh()})})();

(()=>{window.addEventListener('DOMContentLoaded',()=>{let queued=false;function order(){const head=document.querySelector('#sector-view .head .shortcut-actions');if(!head)return;const rank=b=>{const label=b.getAttribute('aria-label')||b.title||'';return /^Voltar/.test(label)?0:/^Fechar/.test(label)?1:b.classList.contains('sort-az')?2:b.classList.contains('unified-expand-toggle')||/Expandir|Recolher/.test(label)&&!b.classList.contains('header-search-circle')?3:b.classList.contains('header-add-circle')?4:b.classList.contains('header-search-circle')?5:b.classList.contains('header-filter-circle')?6:b.classList.contains('header-history-circle')?7:8};const buttons=[...head.children].filter(b=>b.tagName==='BUTTON');const sorted=[...buttons].sort((a,b)=>rank(a)-rank(b));if(buttons.some((b,i)=>b!==sorted[i]))sorted.forEach(b=>head.append(b))}new MutationObserver(()=>{if(queued)return;queued=true;queueMicrotask(()=>{queued=false;order()})}).observe(document.body,{childList:true,subtree:true});order()})})();
(()=>{window.addEventListener('DOMContentLoaded',()=>{const entries=new Map();let queued=false;function sync(){for(const [select,entry]of entries)if(!select.isConnected){entry.button.remove();entries.delete(select)}document.querySelectorAll('.view.show>.panel>.head').forEach(head=>{const actions=head.querySelector('.shortcut-actions');head.querySelectorAll('h2').forEach(h=>{if(h.title!==h.textContent)h.title=h.textContent});if(!actions)return;const selects=[...head.querySelectorAll('.fixed-header-tools select')];if(!selects.length)return;const first=selects[0];if(entries.has(first))return;const button=document.createElement('button');button.type='button';button.className='shortcut-circle header-filter-circle';button.title='Filtros e seleção';button.setAttribute('aria-label','Abrir filtros e seleção');button.innerHTML='<svg viewBox="0 0 24 24" aria-hidden="true"><path d="m5 9 7 7 7-7"/></svg>';let open=false;function toggle(){selects.forEach(s=>{s.hidden=!open;const label=s.closest('label');if(label&&label.closest('.fixed-header-tools'))label.hidden=!open});button.setAttribute('aria-expanded',String(open));button.setAttribute('aria-label',open?'Recolher filtros e seleção':'Abrir filtros e seleção');button.classList.toggle('filters-open',open);const dock=head.querySelector('.fixed-header-tools');if(dock)dock.hidden=![...dock.querySelectorAll('input,select,button')].some(el=>!el.hidden)}button.onclick=()=>{open=!open;toggle()};entries.set(first,{button});actions.append(button);toggle()})}new MutationObserver(()=>{if(queued)return;queued=true;queueMicrotask(()=>{queued=false;sync()})}).observe(document.body,{childList:true,subtree:true});sync()})})();
